"""Independent capstone requests, explicit authorization context, and held-out goals."""

import json
from ml_training.common import ROOT, digest, read_json, write_json

PUBLIC_KEYS = {"id", "text", "version", "resource", "operation", "role", "metadata", "transaction_row", "query_backend"}
BENIGN = [8., .02, 5., 4., 400., 0., 1., 6.]
ABUSIVE = [300., .95, 80., 18., 1., 1., 3.5, 280.]


def build():
    # This fixture is authored before pipeline evaluation and never generated by
    # the routing/query models. API context is explicit user input, not an oracle.
    specifications = [
        ("billing", "Explain the invoice lookup endpoint; the total on my bill looks wrong.", "invoice", "read", "reference", None),
        ("billing", "I need to inspect a refund record for a payment reversal.", "refund", "read", "reference", None),
        ("access", "My API key stopped authenticating. Show its read-only reference.", "api-key", "read", "reference", None),
        ("access", "Help inspect the role that controls my dashboard permissions.", "role", "read", "reference", None),
        ("incident", "Everyone sees server failures. Locate the incident inspection route.", "incident", "read", "reference", None),
        ("incident", "Our service has a widespread outage; I need the incident update reference.", "incident", "update", "reference", None),
        ("billing", "Which endpoint reads the payment method attached to my invoices?", "payment-method", "read", "reference", None),
        ("access", "My login token is rejected; inspect the session token configuration.", "session-token", "read", "reference", None),
        ("device", "Set the thermostat to 22 degrees.", "device-thermostat", "update", "device", {"action":"set_temperature","args":{"celsius":22}}),
        ("device", "Please report the thermostat state without changing anything.", "device-thermostat", "read", "device", {"action":"status","args":{}}),
        ("device", "Schedule the thermostat job at hour 7.", "device-thermostat", "update", "device", {"action":"schedule","args":{"hour":7}}),
        ("device", "Set the room temperature target to 100 Celsius.", "device-thermostat", "update", "device", {"action":"reject","args":{}}),
        ("device", "Make the thermostat comfortable; I cannot choose a temperature.", "device-thermostat", "update", "device", {"action":"reject","args":{}}),
        ("device", "Schedule the temperature controller for hour 24.", "device-thermostat", "update", "device", {"action":"reject","args":{}}),
        ("device", "Set the thermostat to 19 degrees.", "device-thermostat", "update", "denied", None),
        ("device", "Queue a thermostat job at hour 11.", "device-thermostat", "update", "denied", None),
        ("query", "Count tickets where priority equals urgent.", "support-ticket", "read", "query", {"filter":{"field":"priority","op":"eq","value":"urgent"},"aggregate":{"op":"count"}}),
        ("query", "Find ticket IDs where status equals pending.", "support-ticket", "read", "query", {"filter":{"field":"status","op":"eq","value":"pending"},"aggregate":{"op":"ids"}}),
        ("query", "Sum amount where team equals billing AND age_hours is greater than 24.", "support-ticket", "read", "query", {"filter":{"all":[{"field":"team","op":"eq","value":"billing"},{"field":"age_hours","op":"gt","value":24}]},"aggregate":{"op":"sum","field":"amount"}}),
        ("query", "Find the mean of age_hours where priority equals urgent OR amount is greater than 70.", "support-ticket", "read", "query", {"filter":{"any":[{"field":"priority","op":"eq","value":"urgent"},{"field":"amount","op":"gt","value":70}]},"aggregate":{"op":"mean","field":"age_hours"}}),
        ("query", "How many open support tickets have been waiting more than 48 hours?", "support-ticket", "read", "query", {"filter":{"all":[{"field":"status","op":"eq","value":"open"},{"field":"age_hours","op":"gt","value":48}]},"aggregate":{"op":"count"}}),
        ("query", "List ticket IDs where priority does not equal low AND amount is at least 50.", "support-ticket", "read", "query", {"filter":{"all":[{"field":"priority","op":"ne","value":"low"},{"field":"amount","op":"ge","value":50}]},"aggregate":{"op":"ids"}}),
        ("escalate", "I have several unrelated problems and cannot explain which needs attention.", "support-ticket", "read", "clarify", None),
        ("escalate", "Help me decide what to ask; I have not described a problem yet.", "support-ticket", "read", "clarify", None),
        ("escalate", "Billing and access are both broken, and I cannot choose which to handle first.", "support-ticket", "read", "clarify", None),
        ("escalate", "Please help with something outside support, devices, billing and access.", "support-ticket", "read", "clarify", None),
        ("billing", "Read the invoice API reference for my duplicate charge.", "invoice", "read", "blocked", None),
        ("access", "Show the API key inspection endpoint because login fails.", "api-key", "read", "blocked", None),
        ("device", "Set the thermostat to 21 degrees.", "device-thermostat", "update", "blocked", None),
        ("query", "Count tickets where status equals open.", "support-ticket", "read", "blocked", None),
        ("billing", "Inspect the invoice reference while our legitimate batch client is busy.", "invoice", "read", "reference", None),
        ("incident", "Inspect the incident API reference during our legitimate status polling burst.", "incident", "read", "reference", None),
    ]
    rows = []
    for i, (intent, text, resource, operation, outcome, value) in enumerate(specifications):
        version = ["v1", "v2", "v3"][i % 3]
        metadata = ABUSIVE.copy() if outcome == "blocked" else BENIGN.copy()
        if i >= 30:
            metadata = [150., .01, 5., 4., 800., 0., 1., 140.]
        public = {"id": f"capstone-{i:02d}", "text": text, "version": version, "resource": resource,
                  "operation": operation, "role": "viewer" if outcome == "denied" else "operator",
                  "metadata": metadata, "transaction_row": i, "query_backend": "rlvr" if i % 2 else "schema"}
        rows.append({"public": public, "expected": {"intent": intent, "outcome": outcome, "value": value,
                     "doc_id": f"{resource}-{version}-{operation}", "fixture_seed": 88000+i}})
    return rows


def calibration():
    pairs = [
        ("billing", "My invoice payment is duplicated and I need billing help."),
        ("access", "I forgot my password and need to regain account access."),
        ("incident", "The entire platform is unavailable in every region."),
        ("device", "The thermostat should hold the room at 24 degrees."),
        ("query", "Count support tickets with status pending."),
        ("escalate", "I have an unspecified concern and need a person to ask what I mean."),
        ("billing", "This is about an incorrect invoice, not my login credentials."),
        ("access", "My permissions are wrong even though the invoice payment succeeded."),
        ("incident", "Every customer sees server failures; changing a password is irrelevant."),
        ("device", "Read the temperature controller's status."),
        ("query", "Find the count of tickets where team equals security."),
        ("escalate", "Two unrelated requests conflict and I cannot prioritize them."),
    ]
    return [{"id": f"calibration-{i}", "text": text, "intent": intent} for i, (intent, text) in enumerate(pairs)]


def prepare():
    folder = ROOT / "data/generated/hybrid-v1"
    if (folder / "manifest.json").exists():
        load(folder)
        return folder
    folder.mkdir(parents=True, exist_ok=False)
    write_json(folder / "scenarios.json", build())
    write_json(folder / "calibration.json", calibration())
    write_json(folder / "manifest.json", {"version":"hybrid-v1", "synthetic":True,
        "scenario_count":32, "routing_calibration_count":12,
        "policy":"Calibration requests are disjoint from final scenarios. All scenarios remain in every pipeline denominator.",
        "risk_rows":"First 32 held-out D05 rows; unique source rows, no risk-label-based selection.",
        "files":{p.name:digest(p) for p in folder.glob("*.json")}})
    return folder


def load(folder):
    for name, sha in read_json(folder / "manifest.json")["files"].items():
        if digest(folder / name) != sha:
            raise ValueError("Frozen capstone data changed")
    return read_json(folder / "scenarios.json"), read_json(folder / "calibration.json")


def validate_public(request):
    if set(request) != PUBLIC_KEYS:
        raise ValueError("Pipeline accepts public request fields only; oracle/extra fields prohibited")
    if request["version"] not in ["v1","v2","v3"] or request["operation"] not in ["read","update"]:
        raise ValueError("Unsupported API version or operation")
    if request["role"] not in ["viewer","operator"] or request["query_backend"] not in ["schema","rlvr"]:
        raise ValueError("Unsupported authorization or query context")
    if not isinstance(request["text"], str) or len(request["text"]) > 4000:
        raise ValueError("Request must be bounded text")
    if isinstance(request["transaction_row"],bool) or not isinstance(request["transaction_row"],int) or request["transaction_row"] < 0:
        raise ValueError("Invalid transaction row")
